import { cleanCatalog } from './solution';
import type { Catalog, CleanupOptions } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const mutableArtifacts = [
  { path: '/one.JS', kind: 'script' as const, deleted: false },
  { path: 'deleted.js', kind: 'script' as const, deleted: true },
  { path: 'wrong.js', kind: 'style' as const, deleted: false },
  { path: 'skip.txt', kind: 'script' as const, deleted: false },
  { path: 'one.JS', kind: 'script' as const, deleted: false }
];
const emptyArtifacts = [{ path: 'old.css', kind: 'style' as const, deleted: true }];
const bundles = [
  { name: 'scripts', kind: 'script' as const, artifacts: mutableArtifacts },
  { name: 'empty', kind: 'style' as const, artifacts: emptyArtifacts }
];
const catalog: Catalog = { root: '/ignored', bundles };
const options: CleanupOptions = { root: '/assets///', allowedSuffixes: ['.js', '.CSS'] };
const before = JSON.stringify(catalog);
const result = cleanCatalog(catalog, options);

deepEqual(result, {
  root: '/assets',
  bundles: [{
    name: 'scripts',
    kind: 'script',
    artifacts: [
      { path: '/assets/one.JS', kind: 'script', deleted: false },
      { path: '/assets/one.JS', kind: 'script', deleted: false }
    ]
  }]
}, 'catalog is filtered, rooted, ordered, and keeps duplicate paths');
assert(JSON.stringify(catalog) === before, 'inputs are not mutated');
assert(result !== catalog, 'result catalog is new');
assert(result.bundles !== catalog.bundles, 'bundle array is new');
assert(result.bundles[0] !== catalog.bundles[0], 'retained bundle is new');
assert(result.bundles[0].artifacts !== catalog.bundles[0].artifacts, 'artifact array is new');
assert(result.bundles[0].artifacts[0] !== catalog.bundles[0].artifacts[0], 'retained artifact is new');

const noSuffixes = cleanCatalog(catalog, { root: 'root/', allowedSuffixes: [] });
deepEqual(noSuffixes, { root: 'root', bundles: [] }, 'empty suffix list removes all bundles');
deepEqual(cleanCatalog({ root: 'x', bundles: [] }, { root: '/', allowedSuffixes: ['.js'] }), { root: '/', bundles: [] }, 'slash root is preserved');

expectRange(() => cleanCatalog(catalog, { root: '   ', allowedSuffixes: ['.js'] }), 'blank root is rejected');
expectRange(() => cleanCatalog(catalog, { root: '/x', allowedSuffixes: ['js'] }), 'suffix without dot is rejected');
expectRange(() => cleanCatalog(catalog, { root: '/x', allowedSuffixes: [''] }), 'empty suffix is rejected');
expectRange(() => cleanCatalog({
  root: 'x',
  bundles: [{ name: 'bad', kind: 'script', artifacts: [{ path: '', kind: 'script', deleted: false }] }]
}, { root: '/x', allowedSuffixes: ['.js'] }), 'empty artifact path is rejected');

